import { Component, signal, inject, computed } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { StatusService } from '../services/status.service';
import { StatusCardComponent } from './status-card.component';

@Component({
  selector: 'app-downloader',
  standalone: true,
  imports: [CommonModule, FormsModule, StatusCardComponent],
  template: `
    <div class="w-full max-w-6xl mx-auto px-4 pb-20 animate-fade-in">

      <!-- Input Section -->
      <div class="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 mb-8 max-w-2xl mx-auto">
        <label class="block text-sm font-medium text-slate-700 mb-2">
          Enter WhatsApp Number
        </label>

        <div class="flex flex-col sm:flex-row gap-3">
          <div class="relative flex-1 flex">
            <!-- India Country Code (Hardcoded) -->
            <div class="flex items-center justify-center px-4 border border-r-0 border-slate-200 rounded-l-xl bg-slate-50 text-slate-600 font-medium select-none">
              <span class="mr-2 text-lg">🇮🇳</span> +91
            </div>

            <input 
              type="tel" 
              [(ngModel)]="phoneNumber"
              (keyup.enter)="startScan()"
              placeholder="98765 43210"
              maxlength="10"
              class="block w-full px-4 py-3 border border-slate-200 rounded-r-xl leading-5 bg-white placeholder-slate-400 focus:outline-none focus:bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all sm:text-sm font-mono tracking-wide" 
              (input)="filterInput($event)"
            />
          </div>

          <button 
            (click)="startScan()"
            [disabled]="isLoading() || !isValidNumber()"
            class="inline-flex items-center justify-center px-6 py-3 border border-transparent text-sm font-medium rounded-xl text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm min-w-[140px]">
            @if (isLoading()) {
