```typescript
// status.store.ts (Simple Store Pattern)
@Injectable({
  providedIn: 'root'
})
export class StatusStore {
  private readonly _statuses$ = new BehaviorSubject<Status[]>([]);
  private readonly _loading$ = new BehaviorSubject<boolean>(false);
  private readonly _error$ = new BehaviorSubject<string | null>(null);

  readonly statuses$ = this._statuses$.asObservable();
  readonly loading$ = this._loading$.asObservable();
  readonly error$ = this._error$.asObservable();

  readonly vm$ = combineLatest([
    this.statuses$,
    this.loading$,
    this.error$
  ]).pipe(
    map(([statuses, loading, error]) => ({
      statuses,
      loading,
      error
    }))
  );

  setStatuses(statuses: Status[]): void {
    this._statuses$.next(statuses);
  }

  addStatus(status: Status): void {
    const current = this._statuses$.value;
    this._statuses$.next([...current, status]);
  }
}
