import { Injectable, signal, computed, inject } from '@angular/core';
import { ToastService } from './toast.service';

export interface StatusItem {
  id: string;
  type: 'image' | 'video';
  thumbnailUrl: string; // Blob URL
  contentUrl: string;   // Blob URL
  contactName: string; 
  timestamp: Date;
  size: number;
  isArchived: boolean;
  selected?: boolean;
  fileHandle?: any; // FileSystemFileHandle
}

@Injectable({
  providedIn: 'root'
})
export class StatusService {
  private toast = inject(ToastService);

  // State
  private _availableStatuses = signal<StatusItem[]>([]);
  private _archivedStatuses = signal<StatusItem[]>([]);

  // Readonly signals
  availableStatuses = this._availableStatuses.asReadonly();
  archivedStatuses = this._archivedStatuses.asReadonly();

  // Computed
  totalArchived = computed(() => this._archivedStatuses().length);
  storageUsedMB = computed(() => {
    const totalBytes = this._archivedStatuses().reduce((acc, item) => acc + item.size, 0);
    return (totalBytes / (1024 * 1024)).toFixed(1);
  });

  // Database Config
  private readonly DB_NAME = 'KeepArchiveDB';
  private readonly STORE_NAME = 'handles';
  private readonly HANDLE_KEY = 'whatsapp_dir_handle';

  constructor() {
    this.initDB();
  }

  // Initialize IndexedDB for storing handles
  private initDB(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.DB_NAME, 1);
      request.onupgradeneeded = (event: any) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(this.STORE_NAME)) {
          db.createObjectStore(this.STORE_NAME);
        }
      };
      request.onsuccess = () => resolve();
      request.onerror = (e) => reject(e);
    });
  }

  private async getStoredHandle(): Promise<any> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.DB_NAME, 1);
      request.onsuccess = (event: any) => {
        const db = event.target.result;
        const tx = db.transaction(this.STORE_NAME, 'readonly');
        const store = tx.objectStore(this.STORE_NAME);
        const query = store.get(this.HANDLE_KEY);
        query.onsuccess = () => resolve(query.result);
        query.onerror = () => reject(query.error);
      };
      request.onerror = () => reject(request.error);
    });
  }

  private async saveStoredHandle(handle: any): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.DB_NAME, 1);
      request.onsuccess = (event: any) => {
        const db = event.target.result;
        const tx = db.transaction(this.STORE_NAME, 'readwrite');
        const store = tx.objectStore(this.STORE_NAME);
        store.put(handle, this.HANDLE_KEY);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
      };
    });
  }

  /**
   * Main entry point to scan device.
   * Smartly chooses between picking a folder or verifying existing permission.
   */
  async scanLocalDevice(): Promise<void> {
    try {
      // @ts-ignore
      if (typeof window.showDirectoryPicker !== 'function') {
        this.toast.show('Browser not supported. Use Chrome/Edge.', 'error');
        return;
      }

      let dirHandle = await this.getStoredHandle();

      if (dirHandle) {
        // We have a handle, check if we have permission
        // @ts-ignore
        const permission = await dirHandle.queryPermission({ mode: 'read' });

        if (permission !== 'granted') {
          // Request permission again (UI will show this as "Allow Access")
          // @ts-ignore
          const newPermission = await dirHandle.requestPermission({ mode: 'read' });
          if (newPermission !== 'granted') {
            this.toast.show('Permission denied. Please allow access.', 'error');
            return;
          }
        }
      } else {
        // No handle, show picker
        // @ts-ignore
        dirHandle = await window.showDirectoryPicker({
          id: 'whatsapp-status-folder',
          mode: 'read',
          startIn: 'documents' // Try to suggest a good starting point
        });

        // Save for next time
        if (dirHandle) {
          await this.saveStoredHandle(dirHandle);
        }
      }

      await this.readDirectory(dirHandle);

    } catch (err) {
      if ((err as Error).name !== 'AbortError') {
        console.error('Error accessing file system:', err);
        this.toast.show('Failed to access folder', 'error');
      }
      throw err;
    }
  }

  private async readDirectory(dirHandle: any) {
    const newStatuses: StatusItem[] = [];

    // @ts-ignore
    for await (const entry of dirHandle.values()) {
      if (entry.kind === 'file') {
        const file = await entry.getFile();
        if (file.type.startsWith('image/') || file.type.startsWith('video/')) {
          const objectUrl = URL.createObjectURL(file);
          newStatuses.push({
            id: entry.name,
            type: file.type.startsWith('video/') ? 'video' : 'image',
            thumbnailUrl: objectUrl,
            contentUrl: objectUrl,
            contactName: entry.name,
            timestamp: new Date(file.lastModified),
            size: file.size,
            isArchived: false,
            selected: false,
            fileHandle: entry
          });
        }
      }
    }

    newStatuses.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
    this._availableStatuses.set(newStatuses);

    if (newStatuses.length > 0) {
      this.toast.show(`Found ${newStatuses.length} statuses`, 'success');
    } else {
      this.toast.show('No statuses found in selected folder', 'info');
    }
  }

  toggleArchive(id: string) {
    const available = this._availableStatuses();
    const itemToArchive = available.find(s => s.id === id);

    if (this._archivedStatuses().some(s => s.id === id)) {
      this.toast.show('Item already in archive', 'info');
      return; 
    }

    if (itemToArchive) {
      const archivedItem = { ...itemToArchive, isArchived: true, selected: false };
      this._archivedStatuses.update(prev => [archivedItem, ...prev]);
      this._availableStatuses.update(prev => 
        prev.map(s => s.id === id ? { ...s, isArchived: true } : s)
      );
      this.toast.show('Saved to archive', 'success');
      this.triggerBrowserDownload(itemToArchive);
    }
  }

  removeFromArchive(id: string) {
    this._archivedStatuses.update(prev => prev.filter(s => s.id !== id));
    this._availableStatuses.update(prev => 
      prev.map(s => s.id === id ? { ...s, isArchived: false } : s)
    );
    this.toast.show('Removed from archive', 'info');
  }

  clearAvailable() {
    this._availableStatuses().forEach(s => URL.revokeObjectURL(s.contentUrl));
    this._availableStatuses.set([]);
  }

  private triggerBrowserDownload(item: StatusItem) {
    const a = document.createElement('a');
    a.href = item.contentUrl;
    a.download = `KA_${item.contactName}`; 
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }
}

